        ["Sem prichádzajú nové filmy a epizódy. Novinky – Seriály v ňom (aj v podpriečinkoch) hľadajú epizódy, ktoré odošlete na spracovanie; Single a Hromadné spracovanie v ňom otvárajú výber súborov. Súbory v ňom UNIVERSUM len číta."] = "Sem přicházejí nové filmy a epizody. Novinky – Seriály v ní (i v podsložkách) hledají epizody, které odešlete na zpracování; Single a Hromadné zpracování v ní otevírají výběr souborů. Soubory v ní UNIVERSUM jen čte.",
        ["Seriály, ktoré spracúvate pravidelne: keď ich epizódy idú do knižnice, UNIVERSUM si zapamätá názov z TMDB a HISTRA a mená, podľa ktorých ich spoznal (priečinok, začiatok mena súboru). Ďalšie epizódy ho dostanú hneď – bez hľadania; zmeniť ho môžete. Zlý seriál tu zabudnite. Ukladá sa len pre váš účet Windows, nikam sa neposiela."] = "Seriály, které zpracováváte pravidelně: když jejich epizody jdou do knihovny, UNIVERSUM si zapamatuje název z TMDB a HISTRA a jména, podle kterých je poznal (složka, začátek jména souboru). Další epizody ho dostanou hned – bez hledání; změnit ho můžete. Špatný seriál zde zapomeňte. Ukládá se jen pro váš účet Windows, nikam se neposílá.",
