        ["Stačí bezplatný kľúč: zaregistrujte sa na themoviedb.org, v Nastaveniach účtu → API si vyžiadajte kľúč (Developer, osobné použitie) a vložte sem API Key alebo API Read Access Token. Na TMDB sa posiela len názov alebo ID titulu."] = "Stačí bezplatný klíč: zaregistrujte se na themoviedb.org, v Nastavení účtu → API si vyžádejte klíč (Developer, osobní použití) a vložte sem API Key nebo API Read Access Token. Na TMDB se posílá jen název nebo ID titulu.",
