        ["Vlastný token z histra.net (Nastavenia → Tracking API), posiela sa ako hlavička Authorization: Bearer. HISTRA overuje názvy filmov a seriálov nájdené na TMDB (titul, ktorý nepotvrdí, čaká na vaše potvrdenie) a hľadá ich, keď nie je kľúč TMDB alebo TMDB titul nenájde; posiela sa iba hľadaný názov. Na tlačidlo v Listoch z HISTRA načíta vaše listy – do HISTRA UNIVERSUM nič nezapisuje."] = "Vlastní token z histra.net (Nastavení → Tracking API), posílá se jako hlavička Authorization: Bearer. HISTRA ověřuje názvy filmů a seriálů nalezené na TMDB (titul, který nepotvrdí, čeká na vaše potvrzení) a hledá je, když není klíč TMDB nebo TMDB titul nenajde; posílá se jen hledaný název. Tlačítkem v Seznamech z HISTRA načte vaše seznamy – do HISTRA UNIVERSUM nic nezapisuje.",
