        ["Vaše listy filmov a seriálov z histra.net. UNIVERSUM ich z HISTRA len číta (nič tam nezapisuje), uchováva ich len v tomto počítači a obnoví ich iba tlačidlom Synchronizovať."] = "Vaše seznamy filmů a seriálů z histra.net. UNIVERSUM je z HISTRA jen čte (nic tam nezapisuje), uchovává je jen v tomto počítači a obnoví je pouze tlačítkem Synchronizovat.",
