        ["V MOVIES alebo TVSHOWS nového výstupného priečinka sú analyzované súbory – analyzujte priečinok znova (tie sa vynechajú)."] = "V MOVIES nebo TVSHOWS nové výstupní složky jsou analyzované soubory – analyzujte složku znovu (ty se vynechají).",
