        ["(návrh podľa mien súborov – potvrďte)"] = "(návrh podle jmen souborů – potvrďte)",
        ["Vymazať frontu Hromadného spracovania?\n\nZabudnú sa analyzované súbory a rozhodnutia o nich (aj súbory poslané z Noviniek). Na disku sa nič nezmení."] = "Vymazat frontu Hromadného zpracování?\n\nZapomenou se analyzované soubory a rozhodnutí o nich (i soubory poslané z Novinek). Na disku se nic nezmění.",
