        ["Práca je uložená ({0:d. M. yyyy H:mm}) – pri ďalšom otvorení tohto videa sa obnoví."] = "Práce je uložena ({0:d. M. yyyy H:mm}) – při dalším otevření tohoto videa se obnoví.",
