        ["Originál sa po chybe nepodarilo úplne vrátiť do pôvodného stavu: "] = "Originál se po chybě nepodařilo úplně vrátit do původního stavu: ",
        ["Nič nemažte. Vo Fronte úloh je pri úlohe Vrátiť späť; ak nepomôže, pozrite priečinok originálu – súbor s príponou .universum-old alebo .universum-moving je pôvodný."] = "Nic nemažte. Ve Frontě úloh je u úlohy Vrátit zpět; pokud nepomůže, podívejte se do složky originálu – soubor s příponou .universum-old nebo .universum-moving je původní.",
        ["Skúste súbor spracovať znova; ak sa to opakuje, otvorte ho v Informáciách."] = "Zkuste soubor zpracovat znovu; pokud se to opakuje, otevřete ho v Informacích.",
        ["je to výsledok knižnice, nie originál"] = "je to výsledek knihovny, ne originál",
