        ["Súbor už na svojom mieste nie je (presunul sa alebo zmazal)."] = "Soubor už na svém místě není (přesunul se nebo smazal).",
        ["Analyzujte priečinok znova."] = "Analyzujte složku znovu.",
        ["Súbor sa od analýzy zmenil (iná veľkosť, čas alebo stopy)."] = "Soubor se od analýzy změnil (jiná velikost, čas nebo stopy).",
