        ["Hotovo, ale register knižnice sa nepodarilo zapísať ({0})."] = "Hotovo, ale rejstřík knihovny se nepodařilo zapsat ({0}).",
        ["Výsledok je v poriadku; pri ďalšom spracovaní toho istého originálu ho UNIVERSUM nemusí spoznať a zapíše novú verziu."] = "Výsledek je v pořádku; při dalším zpracování téhož originálu ho UNIVERSUM nemusí poznat a zapíše novou verzi.",
        ["Hotovo, ale: {0}."] = "Hotovo, ale: {0}.",
