        ["Skontrolujte disk (miesto, chyby) a spustite spracovanie znova."] = "Zkontrolujte disk (místo, chyby) a spusťte zpracování znovu.",
        ["Nástroj {0} skončil chybou {1}: {2}"] = "Nástroj {0} skončil chybou {1}: {2}",
