        ["mkvpropedit (úprava hlavičky)"] = "mkvpropedit (úprava hlavičky)",
        ["Súbor môže byť poškodený alebo neúplný – otvorte ho v MKVToolNix GUI alebo v Informáciách; skontrolujte aj voľné miesto na disku."] = "Soubor může být poškozený nebo neúplný – otevřete ho v MKVToolNix GUI nebo v Informacích; zkontrolujte i volné místo na disku.",
        ["Kontrola zapísaného súboru našla rozdiel, výsledok sa nepoužil: "] = "Kontrola zapsaného souboru našla rozdíl, výsledek se nepoužil: ",
        ["Originál ostal. Skúste súbor spracovať znova; ak sa to opakuje, otvorte originál v Informáciách – môže byť poškodený alebo mať chybný údaj v hlavičke."] = "Originál zůstal. Zkuste soubor zpracovat znovu; pokud se to opakuje, otevřete originál v Informacích – může být poškozený nebo mít chybný údaj v hlavičce.",
        ["Súbor v knižnici sa nedá nahradiť: {0}."] = "Soubor v knihovně nelze nahradit: {0}.",
        ["Zatvorte program, ktorý ho má otvorený (prehrávač, Jellyfin), a skúste znova."] = "Zavřete program, který ho má otevřený (přehrávač, Jellyfin), a zkuste to znovu.",
