        ["Obraz súboru {0} sa nepodarilo zapísať nanovo: {1}."] = "Obraz souboru {0} se nepodařilo zapsat znovu: {1}.",
        ["Skúste iný kodek alebo kvalitu v Úprave videostopy; pri hardvérovom kodeku skúste softvérový."] = "Zkuste jiný kodek nebo kvalitu v Úpravě videostopy; u hardwarového kodeku zkuste softwarový.",
        ["Zvuk {0} súboru {1} sa nepodarilo zapísať nanovo: {2}."] = "Zvuk {0} souboru {1} se nepodařilo zapsat znovu: {2}.",
        ["Skúste iný kodek v Úprave audiostopy alebo zvuk ponechajte bez prekódovania."] = "Zkuste jiný kodek v Úpravě audiostopy nebo zvuk ponechte bez překódování.",
