        ["OTÁZKA: súbor je v priečinku špeciálov (Season 00), ale meno uvádza sezónu {0:00} – patrí do Season 00 ({1}) alebo do Season {0:00} ({2})? Zadajte číslo epizódy"] = "OTÁZKA: soubor je ve složce speciálů (Season 00), ale jméno uvádí sezónu {0:00} – patří do Season 00 ({1}), nebo do Season {0:00} ({2})? Zadejte číslo epizody",
        ["OTÁZKA: meno uvádza špeciál ({0}), ale súbor je v priečinku Season {1:00} – patrí do Season 00 alebo do Season {1:00} ({2})? Zadajte číslo epizódy"] = "OTÁZKA: jméno uvádí speciál ({0}), ale soubor je ve složce Season {1:00} – patří do Season 00, nebo do Season {1:00} ({2})? Zadejte číslo epizody",
        ["OTÁZKA: epizóda 00 ({0}) – je to špeciál (Season 00) alebo časť sezóny {1:00}? Zadajte číslo epizódy"] = "OTÁZKA: epizoda 00 ({0}) – je to speciál (Season 00), nebo část sezóny {1:00}? Zadejte číslo epizody",
        ["sezóna v mene ({0}) a v priečinku ({1}) sa líšia"] = "sezóna ve jménu ({0}) a ve složce ({1}) se liší",
