        ["Priečinok neexistuje alebo nie je dostupný: "] = "Složka neexistuje nebo není dostupná: ",
        ["Tento priečinok je v knižnici s výsledkami (MOVIES alebo TVSHOWS) – tie Hromadné spracovanie nespracúva, sú to už hotové súbory. Vyberte priečinok s pôvodnými súbormi."] = "Tato složka je v knihovně s výsledky (MOVIES nebo TVSHOWS) – ty Hromadné zpracování nezpracovává, jsou to už hotové soubory. Vyberte složku s původními soubory.",
        ["Do priečinka sa nedá pozrieť: "] = "Do složky nelze nahlédnout: ",
        ["Priamo v priečinku nie sú video súbory, v podpriečinkoch áno – zaškrtnite „aj podpriečinky“ a dajte Analyzovať znova."] = "Přímo ve složce nejsou video soubory, v podsložkách ano – zaškrtněte „i podsložky“ a dejte Analyzovat znovu.",
        ["Všetky video súbory ({0}) sú v knižnici s výsledkami (MOVIES alebo TVSHOWS) – tie Hromadné spracovanie nespracúva."] = "Všechny video soubory ({0}) jsou v knihovně s výsledky (MOVIES nebo TVSHOWS) – ty Hromadné zpracování nezpracovává.",
