        ["Odkiaľ UNIVERSUM číta premiéry a nové epizódy. Webovú stránku pridáte jej súborom pravidiel (Importovať zdroj…); adresy stránok sú len tu v nastaveniach. Stránky sa čítajú slušne: len https, podľa ich robots.txt, najviac jedna stránka za 2 s, bez cookies; každý deň sa pamätá, takže sa nečíta znova."] = "Where UNIVERSUM reads premieres and new episodes from. A web page is added by its rules file (Import a source…); the pages' addresses are only here in the settings. Pages are read politely: https only, following their robots.txt, at most one page every 2 s, no cookies; each day is remembered, so it is not read again.",
