        ["Odstrániť zo zoznamu"] = "Remove from the list",
        ["OpenAI – platené (nepovinné; bez neho kreslí Cloudflare zadarmo)"] = "OpenAI – paid (optional; without it Cloudflare draws for free)",
        ["OpenSubtitles.com (anglické titulky, aj SDH): stačí bezplatný účet – zaregistrujte sa, v profile → API Consumers vytvorte API kľúč a sem vložte kľúč, meno a heslo. svsub.net: váš token (svs_…) – prekladá sa vaším AI kľúčom uloženým v nastaveniach služby. Kľúče a heslo sa ukladajú šifrovane len pre váš účet Windows; nič sa neposiela, kým v Úprave titulkostopy nehľadáte, nesťahujete ani neprekladáte."] = "OpenSubtitles.com (English subtitles, SDH too): a free account is enough – sign up, create an API key in your profile → API Consumers and put the key, user name and password here. svsub.net: your token (svs_…) – it translates with your AI key stored in the service's settings. Keys and the password are stored encrypted for your Windows account only; nothing is sent until you search, download or translate in Subtitle track editing.",
        ["Opraviť chýbajúci index videa (súbor sa zapíše nanovo)"] = "Repair a missing video index (the file is written anew)",
        ["Originál"] = "Original",
