        ["Overiť a uložiť"] = "Verify and save",
        ["Plagáty filmov a seriálov"] = "Film and series posters",
        ["Plagáty v Listoch z HISTRA (a ďalej v Premiérach a Novinkách) sa sťahujú zo servera plagátov a ukladajú v tomto počítači – každý len raz. Posiela sa len adresa obrázka, nič o vás."] = "Posters in the HISTRA lists (and in Premieres and News) are downloaded from the poster server and kept on this computer – each only once. Only the picture's address is sent, nothing about you.",
        ["Posiela sa len nadpis a úvod verejných článkov; prekladá sa každý článok raz, najviac 60 pri jednej aktualizácii a nikdy nad mesačný limit bezplatného kľúča."] = "Only the headline and the opening of public articles are sent; each article is translated once, at most 60 per update and never above the free key's monthly limit.",
