        ["Pripájať sa k TMDB"] = "Connect to TMDB",
        ["Pýta sa len mkvtoolnix.download a github.com, nič o vás sa neposiela."] = "Only mkvtoolnix.download and github.com are asked; nothing about you is sent.",
        ["Resetovať"] = "Reset",
        ["Revízia"] = "Revision",
        ["Rozpoznať jazyk audiostôp ▾"] = "Recognize the audio languages ▾",
        ["Rozpoznať text"] = "Recognize the text",
        ["Sem prichádzajú nové filmy a epizódy. Novinky – Seriály v ňom (aj v podpriečinkoch) hľadajú epizódy, ktoré odošlete na spracovanie; Single a Hromadné spracovanie v ňom otvárajú výber súborov. Súbory v ňom UNIVERSUM len číta."] = "New films and episodes arrive here. News – Series looks in it (subfolders too) for episodes you send for processing; Single and Batch processing open the file choice in it. UNIVERSUM only reads the files in it.",
        ["Seriály, ktoré spracúvate pravidelne: keď ich epizódy idú do knižnice, UNIVERSUM si zapamätá názov z TMDB a HISTRA a mená, podľa ktorých ich spoznal (priečinok, začiatok mena súboru). Ďalšie epizódy ho dostanú hneď – bez hľadania; zmeniť ho môžete. Zlý seriál tu zabudnite. Ukladá sa len pre váš účet Windows, nikam sa neposiela."] = "Series you process regularly: when their episodes go into the library, UNIVERSUM remembers the title from TMDB and HISTRA and the names it recognized them by (folder, start of the file name). Further episodes get it at once – no search; you can change it. Forget a wrong series here. Stored for your Windows account only, sent nowhere.",
        ["Single spracovanie"] = "Single processing",
        ["Skontrolovať teraz…"] = "Check now…",
        ["Skontrolovať titulky videa"] = "Check the video's subtitles",
        ["Sledovať vstupný priečinok – upozorniť na nové filmy a epizódy"] = "Watch the input folder – tell about new films and episodes",
        ["Slová pre forced titulky"] = "Words for forced subtitles",
        ["Slová pre komentáre"] = "Words for commentaries",
        ["Slová pre titulky pre nepočujúcich"] = "Words for subtitles for the deaf (SDH)",
        ["Slová sa hľadajú v pôvodnom názve stopy ako celé slová, bez ohľadu na veľké písmená a diakritiku."] = "The words are looked for in the original track name as whole words, regardless of capitals and accents.",
        ["Spresniť názvy"] = "Refine the titles",
        ["Spustiť"] = "Start",
        ["Spustiť teraz"] = "Start now",
        ["Spustiť zlučovanie"] = "Start multiplexing",
        ["Spustiť znova"] = "Start again",
        ["Späť bez uloženia"] = "Back without saving",
        ["Stačí bezplatný kľúč DeepL API Free (500 000 znakov mesačne): zaregistrujte sa, skopírujte kľúč (končí :fx) a vložte ho sem."] = "A free DeepL API Free key is enough (500,000 characters a month): sign up, copy the key (it ends with :fx) and paste it here.",
        ["Stačí bezplatný kľúč: zaregistrujte sa na themoviedb.org, v Nastaveniach účtu → API si vyžiadajte kľúč (Developer, osobné použitie) a vložte sem API Key alebo API Read Access Token. Na TMDB sa posiela len názov alebo ID titulu."] = "A free key is enough: sign up at themoviedb.org, request a key in Account settings → API (Developer, personal use) and paste the API Key or the API Read Access Token here. Only the title or its ID is sent to TMDB.",
        ["Stopy v týchto jazykoch idú prvé; zvuk v nich znamená, že sa úplné titulky nezapínajú; forced platí len pre ne."] = "Tracks in these languages come first; sound in them means full subtitles are not switched on; forced applies to them only.",
        ["TMDB"] = "TMDB",
        ["TMDB poster"] = "TMDB poster",
        ["TMDB poster – návrh plagátu cez AI a ďalšie hodnotenia"] = "TMDB poster – a poster drawn by AI and more ratings",
        ["TMDB – názvy filmov a seriálov"] = "TMDB – titles of films and series",
        ["Titulky v iných jazykoch sa odstránia – okrem titulkov v jazyku niektorej zvukovej stopy (idú za týmito). V Hromadnom spracovaní ich môžete pri stope ponechať. Prázdne = ponechať všetky titulky."] = "Subtitles in other languages are removed – except those in the language of an audio track (they follow these). In Batch processing you can keep them at the track. Empty = keep all subtitles.",
        ["Titulky – sťahovanie a preklad (vaše účty)"] = "Subtitles – downloads and translation (your accounts)",
        ["Titulok začína teraz"] = "Subtitle starts now",
        ["Uložiť"] = "Save",
