        ["Upraviť…"] = "Edit…",
        ["Veľkosť v názve: hranice SMALL; BIG; BluRay v GB (nad poslednou BluRay BIG)"] = "Size in the name: limits of SMALL; BIG; BluRay in GB (above the last one BluRay BIG)",
        ["Vlastný token z histra.net (Nastavenia → Tracking API), posiela sa ako hlavička Authorization: Bearer. HISTRA overuje názvy filmov a seriálov nájdené na TMDB (titul, ktorý nepotvrdí, čaká na vaše potvrdenie) a hľadá ich, keď nie je kľúč TMDB alebo TMDB titul nenájde; posiela sa iba hľadaný názov. Na tlačidlo v Listoch z HISTRA načíta vaše listy – do HISTRA UNIVERSUM nič nezapisuje."] = "Your own token from histra.net (Settings → Tracking API), sent as the Authorization: Bearer header. HISTRA confirms film and series titles found on TMDB (a title it does not confirm waits for you) and searches them when there is no TMDB key or TMDB finds nothing; only the searched title is sent. A button in HISTRA lists reads your lists – UNIVERSUM writes nothing to HISTRA.",
        ["Vrátiť TVmaze a TMDB"] = "Restore TVmaze and TMDB",
        ["Vrátiť späť"] = "Undo",
        ["Vyberte FREE (1 000 dopytov denne), zadajte e-mail, kľúč príde e-mailom – po kliknutí na aktivačný odkaz ho vložte sem."] = "Choose FREE (1,000 requests a day), enter your e-mail, the key comes by e-mail – after clicking the activation link paste it here.",
