        ["Zdroje noviniek (Premiéry, Novinky – Seriály)"] = "News sources (Premieres, News – Series)",
        ["Zdroje noviniek a zaujímavostí zo sveta filmu: adresa stránky (UNIVERSUM nájde jej kanál RSS) alebo priamo kanála RSS/Atom. Preberá sa len nadpis, krátky úvod a obrázok, celý článok sa otvorí na stránke autora. Adresy sú len tu v nastaveniach."] = "Sources of film news: a page address (UNIVERSUM finds its RSS feed) or the RSS/Atom feed itself. Only the headline, a short opening and the picture are taken; the whole article opens on the author's page. The addresses are only here in the settings.",
