        // stage 2 (1. 11. 2026): the texts of the windows (XAML)
        [" – prehľad dňa a toho, čo UNIVERSUM práve robí."] = " – an overview of the day and of what UNIVERSUM is doing right now.",
        ["+ = titulky rýchlejšie (časy kratšie), − = pomalšie (časy dlhšie)"] = "+ = subtitles faster (times shorter), − = slower (times longer)",
        [", ID stopy"] = ", track ID",
        ["1. titulok je v"] = "Subtitle 1 is at",
        ["1000 = 1 sekunda; kladné = titulky neskôr, záporné = skôr."] = "1000 = 1 second; positive = subtitles later, negative = earlier.",
        ["1000 = 1 sekunda; kladné = zvuk neskôr, záporné = skôr. Samotný posun sa zapíše bez straty kvality (mkvmerge)."] = "1000 = 1 second; positive = audio later, negative = earlier. A shift alone is written without quality loss (mkvmerge).",
        ["2. titulok je v"] = "Subtitle 2 is at",
        ["90 = takmer ako originál, niekoľko stoviek kB; menej = menší súbor"] = "90 = almost like the original, a few hundred kB; less = smaller file",
        ["Agenda"] = "Agenda",
        ["Aj ako úloha (v Plánovaných úlohách)"] = "Also as a task (in Planned tasks)",
        ["Aj tak"] = "Anyway",
        ["Ako prehrávače obraz zobrazia – zapíše sa bez straty kvality (príznak videa)."] = "How players display the picture – written without quality loss (video flag).",
        ["Aktualizovať všetko"] = "Update all",
        ["Bez farebných podkladov"] = "No color backgrounds",
        ["Bez náhľadov (môže ich byť stovky); do priečinkov sérií vedľa epizód – pri spracovanom seriáli s rovnakým menom ako epizóda."] = "No previews (there can be hundreds); into the season folders next to the episodes – for a processed series, with the same name as the episode.",
        ["Celá skupina – filmy každý zvlášť, seriál jedna epizóda"] = "Whole group – films each separately, series one episode",
        ["Celý deň"] = "All day",
