        ["Do novej dávky MEGA spracovania, alebo doplniť čakajúcu dávku"] = "Into a new MEGA processing batch, or add to the waiting batch",
        ["Dole"] = "Down",
        ["Doplnok k názvu"] = "Name addition",
        ["Doplnok:"] = "Addition:",
        ["Druh"] = "Kind",
        ["Dvojklik: prehrávač ide na titulok. Text titulku opravíte klávesom F2 alebo kliknutím do vybraného titulku (riadky oddeľuje „ | “ s medzerami, prázdny text titulok vynechá); pravé tlačidlo: odstrániť titulok, vrátiť úpravy. Upravovať sa dá, keď sú vypnuté opravy celého textu (nepočujúci, formátovanie, prekrývanie časov)."] = "Double-click: the player goes to the subtitle. Correct a subtitle's text with F2 or by clicking into the selected subtitle (lines are separated by “ | ” with spaces, an empty text leaves the subtitle out); right-click: remove subtitle, undo edits. Editing is possible when the whole-text fixes are off (hearing-impaired, formatting, overlapping times).",
        ["Dátový tok (automaticky podľa kodeku a kanálov)"] = "Bitrate (automatic by codec and channels)",
        ["Dátum"] = "Date",
        ["Dávka"] = "Batch",
        ["Dĺžka"] = "Length",
        ["Enabled"] = "Enabled",
        ["Epizóda:"] = "Episode:",
        ["Epizódy"] = "Episodes",
        ["Epizódy bežiacich seriálov za posledný týždeň (staršie sú v Histórii). Zaškrtnite epizódy a odošlite ich na spracovanie: UNIVERSUM ich hneď nájde vo vstupnom priečinku – jeden súbor ide do Single spracovania, viac do Hromadného spracovania. Súbory sa len čítajú."] = "Episodes of running series from the last week (older ones are in History). Tick episodes and send them for processing: UNIVERSUM finds them in the input folder at once – one file goes to Single processing, more to Batch processing. The files are only read.",
        ["Externé textové titulky sa vždy uložia ako SRT v UTF-8. Pri stope videa sa pri zmene textu prečíta celá stopa (číta sa celý súbor)."] = "External text subtitles are always saved as SRT in UTF-8. For a track inside the video, changing the text reads the whole track (the whole file is read).",
        ["Externé titulky pri videu (podľa názvu, slov názvu a čísla epizódy):"] = "External subtitles next to the video (by name, name words and episode number):",
