        ["Nahrá hlas z mikrofónu a prepíše ho v počítači (whisper.cpp) – bez internetu, nahrávka ostane pri poznámke"] = "Records your voice from the microphone and transcribes it on this computer (whisper.cpp) – no internet, the recording stays with the note",
        ["Najbližšia"] = "Nearest",
        ["Najprv sa aktualizuje MKVToolNix, potom UNIVERSUM – inštalátor UNIVERSUM program na konci znova spustí. Inštalátory sa spustia len po overení kontrolného súčtu a podpisu."] = "MKVToolNix is updated first, then UNIVERSUM – the UNIVERSUM installer restarts the program at the end. The installers run only after the checksum and the signature are verified.",
