        ["Nastavenia kalendára – krajiny sviatkov, mená, prázdniny"] = "Calendar settings – holiday countries, names, school holidays",
        ["Nastavenia sa od náhľadu zmenili – vytvorte nový náhľad."] = "The settings have changed since the preview – make a new preview.",
        ["Nastaviť názov výstupného súboru podľa vybraného súboru"] = "Set the output file name from the selected file",
