        ["Normalizovať hlasitosť na −23 LUFS (EBU R128)"] = "Normalize volume to −23 LUFS (EBU R128)",
        ["Novinky, recenzie a zaujímavosti zo sveta filmu – preložené do vášho jazyka, celé články u ich autorov."] = "News, reviews and interesting stories from the film world – translated into your language, full articles at their authors'.",
        ["Nové FPS (video)"] = "New FPS (video)",
        ["Nové prílohy (písma, obrázky)"] = "New attachments (fonts, pictures)",
        ["Náhľad:"] = "Preview:",
        ["Nájde film alebo seriál vo vstupnom priečinku: jeden súbor otvorí v Single spracovaní, viac epizód seriálu v Hromadnom spracovaní"] = "Finds the film or series in the input folder: opens one file in Single processing, several episodes of a series in Batch processing",
        ["Nájde zaškrtnuté epizódy vo vstupnom priečinku a odošle ich na spracovanie"] = "Finds the ticked episodes in the input folder and sends them for processing",
        ["Nájdite film alebo seriál podľa názvu (pôvodný, český, slovenský aj anglický, v akomkoľvek písme, aj s preklepom), s rokom alebo podľa TMDB či IMDb ID. UNIVERSUM odporučí plagát s názvom (CZ → EN → pôvodný jazyk), vybraný uloží ako folder.jpg do priečinka POSTER vo výstupe – alebo k spracovanému filmu či seriálu."] = "Find a film or series by title (original, Czech, Slovak or English, in any script, even with a typo), with the year or by TMDB or IMDb ID. UNIVERSUM recommends a poster with the title (CZ → EN → original language) and saves the chosen one as folder.jpg in the POSTER folder in the output – or with the processed film or series.",
        ["Návrh plagátu cez AI"] = "AI poster suggestion",
