        ["OK"] = "OK",
        ["Obojstranná tlač (okraj striedavo)"] = "Two-sided printing (alternating margin)",
        ["Obrázkové titulky (PGS z Blu-ray, VobSub z DVD) vybranej stopy UNIVERSUM prečíta vlastným rozpoznávaním textu: písmená porovná s písmami Windows, pochybné slová opraví podľa jazyka a tvary, ktoré nepozná, sa opýta – raz za film, zapamätá si ich aj pre ďalšie filmy. Text sa uloží vedľa videa ako „Názov videa.jazyk.srt“ (nikdy cez existujúci súbor, originál ostane) a pridá sa ako nová titulková stopa; časy sú pôvodné časy obrázkov."] = "UNIVERSUM reads the image subtitles (PGS from Blu-ray, VobSub from DVD) of the selected track with its own text recognition: it compares the letters with Windows fonts, corrects doubtful words by language and asks about shapes it does not know – once per film, and remembers them for further films too. The text is saved next to the video as “Video name.language.srt” (never over an existing file, the original stays) and added as a new subtitle track; the times are the original times of the images.",
        ["Obrázky epizód – …-thumb.jpg pri epizódach (seriál)"] = "Episode images – …-thumb.jpg next to the episodes (series)",
        ["Obľúbené"] = "Favorites",
