        ["Poradie riadkov určuje poradie jazykov v súboroch. Súbor, ktorému chýba voliteľná stopa, šablóne stále vyhovuje; ak chýba povinná, ide na kontrolu. Príznaky Default, Enabled a Forced vždy určia pravidlá UNIVERSUM."] = "The order of the rows sets the order of the languages in the files. A file missing an optional track still matches the template; if a required one is missing, it goes for review. The Default, Enabled and Forced flags are always set by the UNIVERSUM rules.",
