        ["Premiéry, nové epizódy, sviatky, prázdniny, meniny a vaše udalosti, úlohy a poznámky na jednom mieste. Kliknite na deň – vľavo uvidíte všetko o ňom. Nič sa tu nesťahuje z internetu: premiéry a epizódy sú tie, ktoré uchovávajú Premiéry a Novinky."] = "Premieres, new episodes, holidays, school holidays, name days and your events, tasks and notes in one place. Click a day – on the left you see everything about it. Nothing is downloaded from the internet here: the premieres and episodes are those kept by Premieres and News.",
