        ["Pripojený súbor pokračuje stopami súboru, ku ktorému patrí (názvy, jazyky a príznaky má od neho); ďalšie časti sa čítajú ako jeden súbor. Pravým tlačidlom na súbore otvoríte ďalšie možnosti."] = "An appended file continues the tracks of the file it belongs to (it takes the names, languages and flags from it); additional parts are read as one file. Right-click a file for more options.",
