        ["Vyberte priečinok s video súbormi (MKV, MP4, AVI, TS, M2TS, MOV, MPG, WebM…) a dajte Analyzovať – čo nie je MKV, uloží sa ako nový MKV."] = "Choose a folder with video files (MKV, MP4, AVI, TS, M2TS, MOV, MPG, WebM…) and click Analyze – anything that is not MKV is saved as a new MKV.",
        ["V MOVIES alebo TVSHOWS nového výstupného priečinka sú analyzované súbory – analyzujte priečinok znova (tie sa vynechajú)."] = "The MOVIES or TVSHOWS folder of the new output folder holds analyzed files – analyze the folder again (they will be left out).",
        ["⚠ súbor nie je v MOVIES ani v TVSHOWS – presuňte ho a dajte Analyzovať"] = "⚠ the file is in neither MOVIES nor TVSHOWS – move it and click Analyze",
        ["(podľa priečinka TVSHOWS)"] = "(by the TVSHOWS folder)",
        ["(podľa priečinka MOVIES)"] = "(by the MOVIES folder)",
        ["(návrh podľa mien súborov – potvrďte)"] = "(suggestion by the file names – confirm)",
        ["Vymazať frontu Hromadného spracovania?\n\nZabudnú sa analyzované súbory a rozhodnutia o nich (aj súbory poslané z Noviniek). Na disku sa nič nezmení."] = "Clear the Batch processing queue?\n\nThe analyzed files and the decisions about them are forgotten (also files sent from News). Nothing changes on the disk.",
        ["Fronta je prázdna – vyberte priečinok a dajte Analyzovať, alebo pošlite epizódy z Noviniek."] = "The queue is empty – choose a folder and click Analyze, or send episodes from News.",
        ["Hromadné spracovanie práve beží – úpravu uložte do úlohy po jeho skončení a novej analýze."] = "Batch processing is running – save the edit to the job after it ends and the folder is analyzed again.",
        ["Hromadné spracovanie už prebehlo (alebo čaká na novú analýzu) – analyzujte priečinok znova a úpravu uložte potom."] = "Batch processing has already run (or is waiting for a new analysis) – analyze the folder again and save the edit then.",
        ["Súbor už nie je v Hromadnom spracovaní – analyzujte priečinok znova."] = "The file is no longer in Batch processing – analyze the folder again.",
        ["{0}: úprava titulkostopy v úlohe – {1}."] = "{0}: subtitle track edit in the job – {1}.",
        ["{0}: revízia – spracuje sa znova; nová verzia sa zapíše a overí, až potom ide doterajší výsledok do Koša."] = "{0}: revision – processed again; the new version is written and verified, only then does the current result go to the Recycle Bin.",
        ["{0}: bez revízie."] = "{0}: no revision.",
        ["{0}: bez doplnku k názvu."] = "{0}: no name addition.",
        ["{0}: doplnok k názvu „{1}“ – nová verzia titulu v knižnici."] = "{0}: name addition “{1}” – a new version of the title in the library.",
        ["Hromadné spracovanie – skupina {0}"] = "Batch processing – group {0}",
        ["Skryť nastavenia ▴"] = "Hide settings ▴",
        ["Zobraziť nastavenia ▾"] = "Show settings ▾",
