        [" + {0} ďalšie"] = " + {0} more",
        ["Idú do Koša Windows (dajú sa z neho obnoviť). Zmaže sa len originál, ktorého výsledok je v knižnici a ktorý sa od spracovania nezmenil; súbory v knižnici (MOVIES, TVSHOWS) sa nikdy nemažú."] = "They go to the Windows Recycle Bin (they can be restored from it). Only an original whose result is in the library and which has not changed since processing is deleted; files in the library (MOVIES, TVSHOWS) are never deleted.",
