        ["pre {0} súbory (verzie jedného filmu)"] = "for {0} files (versions of one film)",
        ["skupina má viac filmov – vyberte súbory v zozname (Ctrl / Shift) alebo zadajte názov pri súbore"] = "the group has several films – select the files in the list (Ctrl / Shift) or enter the title at the file",
        ["TMDB ID je číslo filmu (napr. 12345) alebo adresa z themoviedb.org – minisériál vložte ako adresu …/tv/…."] = "The TMDB ID is a film's number (e.g. 12345) or an address from themoviedb.org – enter a miniseries as an address …/tv/….",
        ["TMDB ID je číslo seriálu (napr. 12345) alebo adresa z themoviedb.org (…/tv/…)."] = "The TMDB ID is a series' number (e.g. 12345) or an address from themoviedb.org (…/tv/…).",
        ["TMDB ID: na načítanie názvu treba kľúč TMDB v Nastaveniach – alebo napíšte Názov (rok) [tmdbid-ID]."] = "TMDB ID: loading the title needs a TMDB key in Settings – or type Title (year) [tmdbid-ID].",
        ["Toto je adresa filmu (/movie/) – seriál má adresu …/tv/…."] = "This is a film's address (/movie/) – a series has the address …/tv/….",
        ["TMDB nepozná seriál s ID {0} – skontrolujte číslo alebo vložte adresu z themoviedb.org."] = "TMDB has no series with ID {0} – check the number or paste an address from themoviedb.org.",
        ["TMDB ID: na načítanie názvu treba kľúč TMDB v Nastaveniach – alebo napíšte Názov (rok)."] = "TMDB ID: loading the title needs a TMDB key in Settings – or type Title (year).",
