        ["Adresa TMDB: na načítanie názvu treba kľúč TMDB v Nastaveniach – alebo napíšte Názov (rok) [tmdbid-{0}]."] = "TMDB address: loading the title needs a TMDB key in Settings – or type Title (year) [tmdbid-{0}].",
        ["POZOR: {0} je na TMDB minisériál alebo TV seriál (TMDB {1}), nie film. V mene súboru nie je číslo série a epizódy, preto sa nedá spracovať ako seriál – uloží sa medzi filmy ako „{2}“ bez TMDB ID. Ak súhlasíte, potvrďte ho pri súbore; inak zvoľte druh seriál a doplňte čísla epizód."] = "WARNING: {0} is a miniseries or TV series on TMDB (TMDB {1}), not a film. The file name has no season and episode number, so it cannot be processed as a series – it is saved among the films as “{2}” without a TMDB ID. If you agree, confirm it at the file; otherwise choose the kind series and add the episode numbers.",
        ["{0} súbory"] = "{0} files",
        ["TMDB nemá názov latinkou – napíšte ho pred rok, napr. Anglický názov {0}."] = "TMDB has no title in Latin script – type it before the year, e.g. English title {0}.",
        ["TMDB nemá anglický názov – použitý je „{0}“ s TMDB ID {1}; ak treba, opravte názov (ID ostane)."] = "TMDB has no English title – “{0}” with TMDB ID {1} is used; correct the title if needed (the ID stays).",
        ["Toto je film – v priečinku TVSHOWS má byť seriál; film presuňte do MOVIES."] = "This is a film – the TVSHOWS folder should hold a series; move the film to MOVIES.",
        ["Adresa TMDB je film (/movie/): druh je filmy a všetky súbory dostali tento názov (verzie jedného filmu) – pri súboroch ho môžete zmeniť."] = "The TMDB address is a film (/movie/): the kind is films and all files got this title (versions of one film) – you can change it at the files.",
        [" Ak je správny, dajte Potvrdiť seriál."] = " If it is right, click Confirm the series.",
        ["{0} žiada spomaliť – čakám {1:0} s a pokračujem…"] = "{0} asks to slow down – waiting {1:0} s and continuing…",
        ["{0} {1} / {2} ({3} rôznych názvov)…"] = "{0} {1} / {2} ({3} different titles)…",
        ["názov v mene súboru sa líši (zhoda {0:0} %)"] = "the title in the file name differs ({0:0} % match)",
