        ["{0} navrhuje {1}: {2} – skontrolujte a potvrďte, alebo vyberte iný titul. "] = "{0} suggests {1}: {2} – check and confirm, or choose another title. ",
        ["{0} našlo len {1} – iný rok, než má súbor"] = "{0} found only {1} – a different year than the file has",
        ["{0} našlo viac titulov ({1}) a žiadny sa nevolá ako súbor"] = "{0} found several titles ({1}) and none is named like the file",
        [" – vyberte správny zo zoznamu pri súbore, napíšte Názov (rok), vložte TMDB ID (číslo alebo adresu z themoviedb.org) alebo potvrďte návrh z mena súboru."] = " – choose the right one from the list at the file, type Title (year), enter the TMDB ID (number or address from themoviedb.org) or confirm the suggestion from the file name.",
        ["Katalóg HISTRA titul nenašiel"] = "The HISTRA catalog did not find the title",
