        [" – návrh je z mena súboru. Ak poznáte TMDB ID, vložte ho do poľa s názvom pri súbore (číslo alebo adresu z themoviedb.org)."] = " – the suggestion is from the file name. If you know the TMDB ID, enter it in the title field at the file (number or address from themoviedb.org).",
        ["{0}: seriál {1}…"] = "{0}: series {1}…",
