        ["Spresnené názvy ({0}): {1} z {2} navrhnutých"] = "Refined titles ({0}): {1} of {2} suggested",
        [", {0} čaká na potvrdenie (⚠ pri súbore – názov sa líšil od mena súboru alebo HISTRA titul nepotvrdila)"] = ", {0} waiting for confirmation (⚠ at the file – the title differed from the file name or HISTRA did not confirm it)",
