        ["Každý originál pôjde do Koša Windows hneď po zapísaní a overení nového súboru v knižnici ({0}). Ak ich chcete ponechať, zvoľte Originál: zachovať."] = "Each original goes to the Windows Recycle Bin right after the new file is written and verified in the library ({0}). To keep them, choose Original: keep.",
