        ["titulky.com je otvorený v prehliadači („{0}“). Stiahnuté titulky (aj ZIP) UNIVERSUM do 30 minút sám vezme zo Stiahnutých súborov, uloží ich vedľa videa a pridá."] = "titulky.com is open in the browser (“{0}”). For 30 minutes UNIVERSUM takes the downloaded subtitles (ZIP too) from Downloads by itself, saves them next to the video and adds them.",
