        ["Vo Windows sa nenašlo žiadne z písiem na porovnanie (Arial, Verdana, Tahoma, Segoe UI …)."] = "None of the fonts for comparison was found in Windows (Arial, Verdana, Tahoma, Segoe UI …).",
        ["Rozpoznávam text {0} titulkov… {1:P0}"] = "Recognizing the text of {0} subtitles… {1:P0}",
        ["Prečítaných {0} z {1} písmen ({2} rôznych tvarov). {3} tvarov UNIVERSUM nepozná – povedzte, čo sú: pýta sa raz za film a zapamätá si ich aj pre ďalšie filmy."] = "Read {0} of {1} letters ({2} different shapes). UNIVERSUM does not know {3} shapes – tell it what they are: it asks once per film and remembers them for other films too.",
