        ["Rozpoznaný text sa nepodarilo uložiť: "] = "The recognized text could not be saved: ",
        ["Priečinok s vašimi titulkami (napr. knižnica) – UNIVERSUM sa z nich naučí slová"] = "Folder with your subtitles (e.g. the library) – UNIVERSUM learns words from them",
        ["Nenašli sa žiadne nové súbory titulkov (SRT, ASS, VTT, SUB), z ktorých by sa UNIVERSUM ešte neučil."] = "No new subtitle files (SRT, ASS, VTT, SUB) that UNIVERSUM has not learned from yet were found.",
        ["Naučené: {0} súborov titulkov, {1:N0} slov ({2}). Slovník je len v tomto počítači."] = "Learned: {0} subtitle files, {1:N0} words ({2}). The lexicon is only on this computer.",
        ["Učenie slovníka je zastavené – čo sa naučilo, ostáva uložené."] = "Learning the lexicon is stopped – what was learned stays saved.",
