        ["Učím sa slová z vašich titulkov… {0} súborov, {1:N0} slov"] = "Learning words from your subtitles… {0} files, {1:N0} words",
        ["Slovník je zatiaľ prázdny – oprava podľa jazyka použije len slová, ktoré UNIVERSUM vo filme prečíta isto. Naučte ho z priečinka s vašimi titulkami."] = "The lexicon is empty so far – correction by the language uses only the words UNIVERSUM reads for sure in the film. Teach it from the folder with your subtitles.",
        ["Slovník z vašich titulkov: "] = "Lexicon from your subtitles: ",
        ["{0} {1:N0} slov"] = "{0} {1:N0} words",
        [" (len v tomto počítači)."] = " (only on this computer).",
        ["Úloha Hromadného spracovania: {0}. Do úlohy sa uložia časy titulkov (FPS, rýchlosť, posun), ponechanie stôp, ich jazyk, Forced a pridané súbory titulkov – súbor sa spracuje s ostatnými (aj v MEGA dávke). Názov stopy a príznak pre nepočujúcich dajú pravidlá, opravy textu sa v úlohe nepoužijú."] = "Batch processing job: {0}. The job keeps the subtitle times (FPS, speed, shift), which tracks stay, their language, Forced and the added subtitle files – the file is processed with the others (also in a MEGA batch). The track name and the hearing-impaired flag come from the rules; text repairs are not used in the job.",
        ["Uložená práca je zahodená – hodnoty na stránke ostali."] = "The saved work is discarded – the values on the page remain.",
        ["Štúdio práve pracuje (ukladá, napasováva alebo sťahuje) – skúste Upraviť v štúdiu o chvíľu."] = "The studio is busy (saving, fitting or downloading) – try Edit in studio in a moment.",
        ["V štúdiu je iné video ako to z úlohy – otvorte ho znova cez Upraviť v štúdiu."] = "The studio has a different video than the job's – open it again with Edit in studio.",
        ["Opravy textu (zmenené titulky, konverzia stopy, prvky pre nepočujúcich, formátovanie, prekrývanie) sa v úlohe nepoužijú – zrušte ich, alebo uložte video hneď tlačidlom Uložiť."] = "Text repairs (changed subtitles, track conversion, hearing-impaired elements, formatting, overlaps) are not used in the job – cancel them, or save the video right away with the Save button.",
        ["Práca je uložená ({0:d. M. yyyy H:mm}) – pri ďalšom otvorení tohto videa sa obnoví."] = "The work is saved ({0:d. M. yyyy H:mm}) – it is restored the next time this video is opened.",
