        ["Zlučovanie sem zapisuje náhľady výsledkov (nikdy nie do výstupných priečinkov); náhľad sa vymaže so svojou kartou alebo po týždni."] = "Multiplexing writes previews of the results here (never into output folders); a preview is deleted with its tab or after a week.",
