        ["Priečinok náhľadov Zlučovania (nie výstupný ani vstupný priečinok)"] = "Folder of the Multiplexing previews (not the output or input folder)",
        ["Náhľady nesmú byť vo výstupnom priečinku (knižnici) ani vo vstupnom priečinku – zvoľte iný. "] = "Previews must not be in the output folder (library) or in the input folder – choose another one. ",
