        ["Adresa sa neuložila – musí to byť https://… bez mena a hesla, napr. "] = "The address was not saved – it must be https://… without a user name and password, e.g. ",
        ["Uložené – plagáty budú zo servera {0} (stiahnuté plagáty ostávajú)."] = "Saved – posters will come from the server {0} (downloaded posters stay).",
        ["TMDB aj HISTRA sú zapnuté – názvy sa hľadajú na TMDB a overujú v katalógu HISTRA (čo TMDB nenájde, hľadá sa v HISTRA); titul, ktorý HISTRA nepotvrdí, čaká na vaše potvrdenie."] = "TMDB and HISTRA are both on – titles are searched on TMDB and confirmed in the HISTRA catalog (what TMDB does not find is searched in HISTRA); a title HISTRA does not confirm waits for your confirmation.",
        ["Zapnuté je len TMDB."] = "Only TMDB is on.",
        ["Zapnutá je len HISTRA – názvy sa hľadajú v jej katalógu (podľa názvu a roku; ID a adresy TMDB a epizódy overí len TMDB)."] = "Only HISTRA is on – titles are searched in its catalog (by title and year; TMDB IDs, addresses and episodes are verified only by TMDB).",
