        ["Len české a slovenské filmy (aj koprodukcie) – premiéry v kinách na Slovensku a v Česku (sledované {0} dní dopredu), s dátumom na VOD a v TV. Zdroj: TMDB."] = "Czech and Slovak films only (co-productions too) – cinema premieres in Slovakia and Czechia (tracked {0} days ahead), with the VOD and TV dates. Source: TMDB.",
        ["Filmy sveta okrem českých a slovenských – najpopulárnejšie s prvou premiérou vo svete (sledované {0} dní dopredu); ak idú aj do našich kín, dátum je pri premiére. Zdroj: TMDB."] = "World films except Czech and Slovak ones – the most popular, with their first premiere worldwide (tracked {0} days ahead); if they also come to local cinemas, the date is with the premiere. Source: TMDB.",
