        ["Zmazať {0} dávky {1}?\n\nIdú do Koša Windows (dajú sa z neho obnoviť). Zmaže sa len originál, ktorého výsledok je v knižnici a ktorý sa od prípravy dávky nezmenil; súbory v knižnici sa nikdy nemažú."] = "Delete {0} of {1}?\n\nThey go to the Windows Recycle Bin (they can be restored from it). Only an original whose result is in the library and which has not changed since the batch was prepared is deleted; files in the library are never deleted.",
