        ["Odstrániť {0} z MEGA spracovania?\n\n{1}\n\nSúbory sa nemenia; tie, čo sa ešte nezapísali, sa v Hromadnom spracovaní znova ukážu ako voľné."] = "Remove {0} from MEGA processing?\n\n{1}\n\nThe files do not change; those not written yet show up as free in Batch processing again.",
