        ["Kľúčové snímky sa nedajú prečítať ({0}) – strih bez prekódovania nevie, kde úseky začnú; zapnite Presný strih."] = "The key frames cannot be read ({0}) – a cut without re-encoding does not know where the sections start; turn on Precise cut.",
        ["Kľúčové snímky sa ešte čítajú – strih bez prekódovania počká na ne (alebo zapnite Presný strih)."] = "The key frames are still being read – a cut without re-encoding waits for them (or turn on Precise cut).",
        ["Video nemá označené kľúčové snímky – strih bez prekódovania nie je možný; zapnite Presný strih."] = "The video has no marked key frames – a cut without re-encoding is not possible; turn on Precise cut.",
        ["Úsek {0} je kratší ako vzdialenosť kľúčových snímok – nezostalo by z neho nič; predĺžte ho alebo zapnite Presný strih."] = "Section {0} is shorter than the distance between key frames – nothing of it would remain; lengthen it or turn on Precise cut.",
