        ["Preklady: DeepL"] = "Translations: DeepL",
        ["Zapísaný nový súbor (mkvmerge) a skontrolovaný: stopy, jazyky, príznaky, názvy a dĺžka sedia."] = "New file written (mkvmerge) and checked: tracks, languages, flags, names and duration match.",
        ["Upravená len hlavička súboru (mkvpropedit) a skontrolovaná."] = "Only the file header was edited (mkvpropedit) and checked.",
        ["Súbor sa nemusel meniť – len sa uložil do knižnice."] = "The file did not need changing – it was only saved to the library.",
