        ["Nespracované – súbor treba najprv skontrolovať v Hromadnom alebo Single spracovaní"] = "Not processed – the file must first be checked in Batch or Single processing",
        ["Zrušené – originál ostal nezmenený"] = "Canceled – the original stayed unchanged",
        ["POZOR – nepodarilo sa a originál sa nepodarilo úplne vrátiť"] = "WARNING – failed, and the original could not be fully restored",
        ["Chyba – originál je vrátený do pôvodného stavu"] = "Error – the original is restored to its previous state",
        ["Chyba – originál ostal nezmenený"] = "Error – the original stayed unchanged",
        ["Výsledok z rovnakého originálu s rovnakými rozhodnutiami už je v knižnici: {0} – nič sa nezapísalo."] = "A result from the same original with the same decisions is already in the library: {0} – nothing was written.",
        ["Spracovanie sa nepodarilo (podrobnosti sú v technických riadkoch)."] = "Processing failed (details are in the technical lines).",
        ["Skúste súbor spracovať znova; ak sa chyba opakuje, otvorte ho v Informáciách alebo v MKVToolNix GUI."] = "Try processing the file again; if the error repeats, open it in Information or in MKVToolNix GUI.",
        ["Preskočené – už je v knižnici"] = "Skipped – already in the library",
        ["Preskočené pri kontrole pred spustením"] = "Skipped at the check before the start",
        ["Otvorte súbor znova v Hromadnom spracovaní, skontrolujte ho a pošlite ho do dávky znova."] = "Open the file in Batch processing again, check it and send it to the batch again.",
        ["Kontajner {0} sa zmení na MKV."] = "The {0} container becomes MKV.",
        ["pridaná zo súboru {0}."] = "added from the file {0}.",
