        ["Doplnený index (Cues) – posúvanie v prehrávači bude rýchle."] = "Index (Cues) added – seeking in the player will be fast.",
        ["Odstránené tagy (údaje, ktoré pridali iné programy)."] = "Tags removed (data added by other programs).",
