        ["Kapitoly: {0} → {1}."] = "Chapters: {0} → {1}.",
        ["Originál je v Koši (výsledok je zapísaný a skontrolovaný)."] = "The original is in the Recycle Bin (the result is written and checked).",
        ["Originál je vrátený do pôvodného stavu."] = "The original is restored to its previous state.",
        ["Starší výsledok toho istého originálu (s inými rozhodnutiami) je v Koši: {0}."] = "An earlier result of the same original (with other decisions) is in the Recycle Bin: {0}.",
        ["Originál ostal na mieste – {0}."] = "The original stayed in place – {0}.",
        ["Originál sa po chybe nepodarilo úplne vrátiť do pôvodného stavu: "] = "After the error, the original could not be fully restored to its previous state: ",
        ["Nič nemažte. Vo Fronte úloh je pri úlohe Vrátiť späť; ak nepomôže, pozrite priečinok originálu – súbor s príponou .universum-old alebo .universum-moving je pôvodný."] = "Do not delete anything. In the Job queue the job has Undo; if that does not help, look in the original's folder – the file with the extension .universum-old or .universum-moving is the original.",
        ["Skúste súbor spracovať znova; ak sa to opakuje, otvorte ho v Informáciách."] = "Try processing the file again; if it happens again, open it in Information.",
        ["je to výsledok knižnice, nie originál"] = "it is a library result, not an original",
        ["nedá sa presunúť do Koša"] = "it cannot be moved to the Recycle Bin",
        ["Súbor už na svojom mieste nie je (presunul sa alebo zmazal)."] = "The file is no longer in its place (it was moved or deleted).",
        ["Analyzujte priečinok znova."] = "Analyze the folder again.",
        ["Súbor sa od analýzy zmenil (iná veľkosť, čas alebo stopy)."] = "The file changed since the analysis (a different size, time or tracks).",
        ["Analyzujte ho znova a spustite spracovanie."] = "Analyze it again and start the processing.",
        ["Pridaný súbor {0} (titulky alebo zvuk) už neexistuje."] = "The added file {0} (subtitles or audio) no longer exists.",
        ["Pridajte ho znova alebo analyzujte priečinok znova."] = "Add it again or analyze the folder again.",
        ["Hotovo, ale register knižnice sa nepodarilo zapísať ({0})."] = "Done, but the library index could not be written ({0}).",
        ["Výsledok je v poriadku; pri ďalšom spracovaní toho istého originálu ho UNIVERSUM nemusí spoznať a zapíše novú verziu."] = "The result is fine; the next time the same original is processed, UNIVERSUM may not recognize it and will write a new version.",
        ["Hotovo, ale: {0}."] = "Done, but: {0}.",
        ["Výsledok je v knižnici; skontrolujte uvedenú vec."] = "The result is in the library; check the matter mentioned.",
        ["Na disku {0} je voľných {1} MB, treba {2} MB."] = "The disk {0} has {1} MB free, {2} MB is needed.",
        ["Uvoľnite miesto na disku alebo zvoľte knižnicu na inom disku a spustite spracovanie znova."] = "Free up disk space or choose a library on another disk and start the processing again.",
        ["Kópia súboru do knižnice je neúplná."] = "The copy of the file in the library is incomplete.",
        ["Skontrolujte disk (miesto, chyby) a spustite spracovanie znova."] = "Check the disk (space, errors) and start the processing again.",
        ["Nástroj {0} skončil chybou {1}: {2}"] = "The tool {0} ended with error {1}: {2}",
        ["mkvmerge (zápis nového súboru)"] = "mkvmerge (writing a new file)",
        ["mkvpropedit (úprava hlavičky)"] = "mkvpropedit (header editing)",
        ["Súbor môže byť poškodený alebo neúplný – otvorte ho v MKVToolNix GUI alebo v Informáciách; skontrolujte aj voľné miesto na disku."] = "The file may be damaged or incomplete – open it in MKVToolNix GUI or in Information; also check the free disk space.",
        ["Kontrola zapísaného súboru našla rozdiel, výsledok sa nepoužil: "] = "The check of the written file found a difference, the result was not used: ",
        ["Originál ostal. Skúste súbor spracovať znova; ak sa to opakuje, otvorte originál v Informáciách – môže byť poškodený alebo mať chybný údaj v hlavičke."] = "The original stayed. Try processing the file again; if it happens again, open the original in Information – it may be damaged or have a wrong value in its header.",
        ["Súbor v knižnici sa nedá nahradiť: {0}."] = "The file in the library cannot be replaced: {0}.",
        ["Zatvorte program, ktorý ho má otvorený (prehrávač, Jellyfin), a skúste znova."] = "Close the program that has it open (player, Jellyfin) and try again.",
        ["Nahradený súbor ostal ako {0} ({1})."] = "The replaced file stayed as {0} ({1}).",
        ["Po kontrole výsledku ho môžete zmazať sami."] = "After checking the result you can delete it yourself.",
        ["Zvuk sa mal zapísať nanovo, ale chýba FFmpeg."] = "The audio was to be re-encoded, but FFmpeg is missing.",
        ["Preinštalujte UNIVERSUM – FFmpeg je súčasťou inštalácie."] = "Reinstall UNIVERSUM – FFmpeg is part of the installation.",
        ["Obraz súboru {0} sa nepodarilo zapísať nanovo: {1}."] = "The picture of the file {0} could not be re-encoded: {1}.",
        ["Skúste iný kodek alebo kvalitu v Úprave videostopy; pri hardvérovom kodeku skúste softvérový."] = "Try another codec or quality in Video track editing; with a hardware codec, try a software one.",
        ["Zvuk {0} súboru {1} sa nepodarilo zapísať nanovo: {2}."] = "Audio {0} of the file {1} could not be re-encoded: {2}.",
        ["Skúste iný kodek v Úprave audiostopy alebo zvuk ponechajte bez prekódovania."] = "Try another codec in Audio track editing or keep the audio without re-encoding.",
        ["Titulky stopy {0} sa nepodarilo prečítať na strih."] = "The subtitles of track {0} could not be read for the cut.",
        ["Strihajte bez týchto titulkov, alebo ich najprv uložte ako SRT v Úprave titulkostopy."] = "Cut without these subtitles, or first save them as SRT in Subtitle track editing.",
        ["Starší výsledok toho istého originálu ostal ({0}): {1} – po kontrole ho môžete zmazať sami."] = "An earlier result of the same original stayed ({0}): {1} – after checking you can delete it yourself.",
