        ["OTÁZKA: meno uvádza špeciál ({0}), ale súbor je v priečinku Season {1:00} – patrí do Season 00 alebo do Season {1:00} ({2})? Zadajte číslo epizódy"] = "QUESTION: the name gives a special ({0}), but the file is in the Season {1:00} folder – does it belong to Season 00 or to Season {1:00} ({2})? Enter the episode number",
