        ["Priamo v priečinku nie sú video súbory, v podpriečinkoch áno – zaškrtnite „aj podpriečinky“ a dajte Analyzovať znova."] = "There are no video files directly in the folder, but there are in subfolders – check “subfolders too” and click Analyze again.",
        ["Všetky video súbory ({0}) sú v knižnici s výsledkami (MOVIES alebo TVSHOWS) – tie Hromadné spracovanie nespracúva."] = "All video files ({0}) are in the library with the results (MOVIES or TVSHOWS) – Batch processing does not process those.",
