        ["Doplnok do názvu pred veľkostnú triedu – iná verzia titulu (napr. Directors Cut, Remaster, 2); písmená, číslice, medzery a pomlčky, najviac 30 znakov. Jellyfin ho ukáže ako názov verzie."] = "Addition to the name before the size class – another version of the title (e.g. Directors Cut, Remaster, 2); letters, digits, spaces and hyphens, at most 30 characters. Jellyfin shows it as the version name.",
        ["Doplnok k názvu pred veľkostnú triedu – iná verzia titulu (napr. Directors Cut, Remaster, 2); písmená, číslice, medzery a pomlčky, najviac 30 znakov. Jellyfin ho ukáže ako názov verzie."] = "Name addition before the size class – another version of the title (e.g. Directors Cut, Remaster, 2); letters, digits, spaces and hyphens, at most 30 characters. Jellyfin shows it as the version name.",
        ["Dočasné súbory po prerušenom spracovaní presunie do Koša"] = "Moves temporary files left by interrupted processing to the Recycle Bin",
        ["Druh (filmy alebo seriál) je odhadnutý z mien súborov – potvrďte ho, alebo zvoľte druhý"] = "The kind (films or series) is guessed from the file names – confirm it or choose the other one",
        ["Druh, názvy a čísla epizód odhadnuté z mien súborov a priečinkov (nie otázky Season 00 / Season 01)"] = "Kind, titles and episode numbers guessed from the file and folder names (not the Season 00 / Season 01 questions)",
        ["Dávka odoslaná so „zmazať ručne“: originály jej zapísaných súborov do Koša Windows"] = "Batch sent with “delete manually”: the originals of its written files go to the Windows Recycle Bin",
        ["Dávku nižšie"] = "Move the batch down",
        ["Dávku vyššie (poradie pre „po predchádzajúcej dávke“)"] = "Move the batch up (order for “after the previous batch”)",
        ["Epizódy ďalších seriálov poslané z Noviniek spolu s prvým – každá ide do priečinka svojho seriálu (vidno v stĺpci Cieľ v knižnici)"] = "Episodes of other series sent from News together with the first one – each goes to its own series' folder (shown in the Target in the library column)",
        ["Film: Názov (rok), napr. Creep (2004). Seriál: číslo epizódy, napr. S01E04."] = "Film: Title (year), e.g. Creep (2004). Series: episode number, e.g. S01E04.",
        ["Globálne tagy aj tagy stôp (názvy, štatistiky, údaje o kódovaní)"] = "Global tags and track tags (names, statistics, encoding data)",
        ["HISTRA tento seriál nepotvrdila – potvrďte ho, ak je správny (alebo zadajte iný)"] = "HISTRA did not confirm this series – confirm it if it is correct (or enter another one)",
        ["História, posledný týždeň aj nadchádzajúce – všetky informácie"] = "History, the last week and upcoming – all information",
        ["Hodnoty všetkých titulkov tohto videa sa zapamätajú – pri ďalšom otvorení videa sa obnovia (nič sa nezapíše do súborov)"] = "The values of all subtitles of this video are remembered – they are restored the next time the video is opened (nothing is written to the files)",
        ["Hodnoty všetkých zvukov tohto videa (aj pridané súbory) sa zapamätajú – pri ďalšom otvorení videa sa obnovia (nič sa nezapíše do súborov)"] = "The values of all audio of this video (added files too) are remembered – they are restored the next time the video is opened (nothing is written to the files)",
        ["Hľadať film alebo seriál v listoch (český aj pôvodný názov, rok; bez diakritiky)"] = "Search for a film or series in the lists (Czech and original title, year; accents not needed)",
        ["Hľadať list podľa názvu (bez diakritiky)"] = "Search for a list by name (accents not needed)",
        ["Hľadať názov, produkciu alebo poznámku (bez diakritiky)"] = "Search for a title, production or note (accents not needed)",
        ["Hľadať seriál, stanicu alebo poznámku (bez diakritiky)"] = "Search for a series, channel or note (accents not needed)",
        ["Hľadať v nadpisoch a úvodoch (bez diakritiky)"] = "Search the headlines and openings (accents not needed)",
        ["Hľadať v návode (aj bez diakritiky)"] = "Search the guide (accents not needed)",
        ["Iné titulky hore na obraze (žlté), so svojimi zmenami"] = "Other subtitles at the top of the picture (yellow), with their own changes",
        ["Iné titulky, ktoré k filmu sedia (aj v inom jazyku)"] = "Other subtitles that fit the film (also in another language)",
        ["Jazyk každej textovej titulkovej stopy UNIVERSUM číta po analýze sám – niekoľko častí filmu ako pri zvuku (forced titulky tam, kde ich súbor má podľa indexu). Tu ho prečíta znova pre vybranú skupinu."] = "UNIVERSUM reads the language of every text subtitle track by itself after the analysis – several parts of the film, as with audio (forced subtitles where the file has them according to the index). Here it reads it again for the selected group.",
        ["Kapitoly XML alebo OGM (.txt)"] = "XML or OGM chapters (.txt)",
        ["Každý originál ide do Koša hneď po zapísaní a overení nového súboru v knižnici – priebežne, súbor po súbore"] = "Each original goes to the Recycle Bin right after the new file is written and verified in the library – continuously, file by file",
        ["Každý súbor s videom dostane vlastné nastavenia; titulky a zvuk za ním pôjdu k nemu"] = "Each video file gets its own settings; the subtitles and audio after it go with it",
        ["Kde sa dá titul legálne pozerať (SK, CZ) – údaje JustWatch cez TMDB"] = "Where the title can be watched legally (SK, CZ) – JustWatch data via TMDB",
        ["Kde sa vo filme hovorí – osem častí filmu, aj iné FPS (25 ↔ 23,976 …)"] = "Where speech occurs in the film – eight parts of the film, other FPS too (25 ↔ 23.976 …)",
        ["Keď sa do vstupného priečinka dokopíruje film alebo epizóda, hore sa ukáže upozornenie s tlačidlom Do Hromadného spracovania. Nič sa nespracuje samo."] = "When a film or episode finishes copying into the input folder, a notice with the To Batch processing button appears at the top. Nothing is processed automatically.",
        ["Kľúč DeepL API (bezplatný končí :fx)"] = "DeepL API key (a free one ends with :fx)",
        ["Len seriály zaškrtnuté v stĺpci Vybrané"] = "Only series ticked in the Selected column",
        ["Len tituly zaškrtnuté v stĺpci Vybrané"] = "Only titles ticked in the Selected column",
        ["Meno zdroja"] = "Source name",
        ["Meno účtu OpenSubtitles.com"] = "OpenSubtitles.com user name",
        ["Mesto alebo obec, napr. Valaská"] = "City or town, e.g. Valaská",
        ["Model AI (napr. gpt-6-astra); prázdne = predvolený model služby. Úroveň uvažovania API svsub.net nepozná."] = "AI model (e.g. gpt-6-astra); empty = the service's default model. The svsub.net API has no reasoning level.",
        ["Má hlasovú nahrávku"] = "Has a voice recording",
        ["Nahradí zoznam kapitolami po celej dĺžke súboru"] = "Replaces the list with chapters across the whole length of the file",
        ["Najbližší titulok vybraných titulkov sa posunie tak, aby začínal práve teraz (posun sa zmení o rozdiel)"] = "The nearest subtitle of the selected subtitles is shifted to start right now (the shift changes by the difference)",
        ["Napríklad každú noc o 3:00 obnoviť Premiéry a Novinky alebo synchronizovať listy HISTRA"] = "For example, refresh Premieres and News every night at 3:00 or synchronize the HISTRA lists",
        ["Napríklad: zajtra o 20:00 spracovať film #kino !  ·  do piatku zavolať  ·  za 3 dni …  – Enter pridá"] = "For example: tomorrow at 20:00 process film #cinema !  ·  call by Friday  ·  in 3 days …  – Enter adds",
        ["Nastaví rýchlosť (alebo zmenu FPS) a posun vybraných titulkov, keď je výsledok istý; oboje naraz = istota, keď sa zhodnú"] = "Sets the speed (or FPS change) and shift of the selected subtitles when the result is certain; both at once = certainty when they agree",
        ["Neistý výsledok sa sám nepoužije – nastaví ho až toto tlačidlo; overte ho prehraním"] = "An uncertain result is not applied by itself – only this button sets it; verify it by playing",
        ["Nová kapitola za vybranou (o minútu neskôr)"] = "New chapter after the selected one (one minute later)",
        ["Nová udalosť vo vybraný deň"] = "New event on the selected day",
        ["Nové nastavenia zlučovania (nový výstupný súbor)"] = "New multiplex settings (new output file)",
        ["Nový API token"] = "New API token",
        ["Nový kľúč OMDb"] = "New OMDb key",
        ["Nový kľúč OpenAI (sk-…)"] = "New OpenAI key (sk-…)",
        ["Nový kľúč TMDB"] = "New TMDB key",
        ["Nový riadok kontrolného zoznamu – Enter ho pridá"] = "New checklist item – Enter adds it",
        ["Nový token HISTRA"] = "New HISTRA token",
        ["Nájde mestá s týmto menom; ak ich je viac, vyberiete to správne"] = "Finds cities with this name; if there are several, you choose the right one",
        ["Návod vytlačiť alebo uložiť ako PDF či HTML"] = "Print the guide or save it as PDF or HTML",
        ["Návrh nie je istý (názov sa líšil od mena súboru alebo HISTRA titul nepotvrdila) – potvrďte ho, ak je správny, alebo vyberte iný"] = "The suggestion is not certain (the title differed from the file name or HISTRA did not confirm the title) – confirm it if it is correct, or choose another one",
        ["Názov (aj s rokom, napr. „Názov 2024“), TMDB ID (číslo alebo adresa z themoviedb.org) alebo IMDb ID (tt a číslice)"] = "Title (with the year too, e.g. “Title 2024”), TMDB ID (number or address from themoviedb.org) or IMDb ID (tt and digits)",
        ["Názov (rok), pri inom písme ako latinka anglický názov (rok) [tmdbid-ID]; aj ID alebo adresa TMDB"] = "Title (year), for a non-Latin script the English title (year) [tmdbid-ID]; also a TMDB ID or address",
        ["Názov (rok), pri inom písme ako latinka anglický názov (rok) [tmdbid-ID]; aj ID alebo adresa TMDB. Platí pre film vybranej skupiny (aj jeho verzie)."] = "Title (year), for a non-Latin script the English title (year) [tmdbid-ID]; also a TMDB ID or address. Applies to the film of the selected group (its versions too).",
        ["Názov (rok), pri inom písme ako latinka anglický názov (rok) [tmdbid-ID]; aj adresa TMDB (/movie/ = film, /tv/ = seriál)"] = "Title (year), for a non-Latin script the English title (year) [tmdbid-ID]; also a TMDB address (/movie/ = film, /tv/ = series)",
        ["Názov celého súboru, ktorý ukazujú prehrávače; prázdny ho odstráni"] = "Title of the whole file that players show; empty removes it",
        ["Názov stopy vo výsledku pre celú skupinu – môžete ho prepísať alebo doň dopísať (potvrdí sa po opustení poľa); prázdny = bez názvu"] = "Track name in the result for the whole group – you can overwrite it or add to it (confirmed when you leave the field); empty = no name",
        ["Názov stopy vo výsledku – kým ho neprepíšete, dáva ho pravidlo (forced = „Forced“, inak bez názvu); môžete doň dopísať, prázdny = bez názvu"] = "Track name in the result – until you overwrite it, the rule sets it (forced = “Forced”, otherwise no name); you can add to it, empty = no name",
        ["Názov stopy vo výsledku – kým ho neprepíšete, dáva ho pravidlo (zvuk bez názvu); môžete doň dopísať, prázdny = bez názvu"] = "Track name in the result – until you overwrite it, the rule sets it (audio without a name); you can add to it, empty = no name",
        ["Názov stopy vo výsledku – môžete ho prepísať alebo doň dopísať (potvrdí sa po opustení poľa); prázdny = bez názvu"] = "Track name in the result – you can overwrite it or add to it (confirmed when you leave the field); empty = no name",
        ["Obrázky pôjdu k spracovanému filmu (MOVIES) alebo seriálu (TVSHOWS); keď je zatiaľ len na vstupe, počkajú, kým ho UNIVERSUM spracuje"] = "The images go to the processed film (MOVIES) or series (TVSHOWS); while it is only in the input so far, they wait until UNIVERSUM processes it",
        ["Odpoveď na otázku Season 00 alebo bežná sezóna: súbory z priečinka špeciálov (alebo s S00 v mene) idú do Season 00. Inak zadajte číslo epizódy pri súbore."] = "Answer to the question Season 00 or a regular season: files from the specials folder (or with S00 in the name) go to Season 00. Otherwise enter the episode number at the file.",
        ["Odstráni vybraný zdrojový súbor (aj jeho stopy), časť alebo pripojený súbor"] = "Removes the selected source file (with its tracks), part or appended file",
        ["Odstráni všetky zdrojové súbory zo Zlučovania (na disku sa nič nezmení)"] = "Removes all source files from Multiplexing (nothing changes on the disk)",
        ["Odstrániť odkaz z poznámky"] = "Remove the link from the note",
        ["OpenSubtitles.com – API kľúč (uložený sa nezobrazuje)"] = "OpenSubtitles.com – API key (a saved one is not shown)",
        ["Originály spracovaných súborov do Koša Windows – len tie, ktorých výsledok je v knižnici a ktoré sa od spracovania nezmenili"] = "Originals of the processed files to the Windows Recycle Bin – only those whose result is in the library and that have not changed since processing",
        ["Otvoriť na HISTRA"] = "Open on HISTRA",
        ["Otvoriť na TMDB"] = "Open on TMDB",
        ["Otvoriť v Prieskumníkovi"] = "Open in File Explorer",
        ["Otvoriť v zdroji"] = "Open in the source",
        ["Otvorí dávku so všetkými rozhodnutiami v Hromadnom spracovaní – opravíte ju a dáte Uložiť do dávky"] = "Opens the batch with all decisions in Batch processing – correct it and click Save to batch",
        ["Otvorí https://histra.net/settings/tracking-api"] = "Opens https://histra.net/settings/tracking-api",
        ["Otvorí náhľad v prehrávači, ktorý má Windows pre MKV"] = "Opens the preview in the player Windows uses for MKV",
        ["Otvorí priečinok s originálom v Prieskumníkovi"] = "Opens the folder with the original in File Explorer",
        ["Otvorí priečinok s výsledkom v Prieskumníkovi"] = "Opens the folder with the result in File Explorer",
        ["Podľa titulu (s TMDB ID presne) a epizódy; účet a API kľúč v Nastaveniach"] = "By title (exactly with a TMDB ID) and episode; account and API key in Settings",
        ["Poradie vo výstupe"] = "Order in the output",
        ["Porovná každú titulkovú stopu videa so zvukom: sedí, mešká, ide skôr, iné FPS"] = "Compares each subtitle track of the video with the audio: in sync, late, early, different FPS",
        ["Poskytovateľ AI, ktorým svsub.net prekladá (váš kľúč je v nastaveniach služby)"] = "The AI provider svsub.net translates with (your key is in the service's settings)",
        ["Posunúť nižšie (Ctrl+↓)"] = "Move down (Ctrl+↓)",
        ["Posunúť vyššie (Ctrl+↑)"] = "Move up (Ctrl+↑)",
        ["Posunúť vyššie (Ctrl+↑) – zvuk medzi zvukom, titulky medzi titulkami"] = "Move up (Ctrl+↑) – audio among audio, subtitles among subtitles",
        ["Posunúť záložky doprava"] = "Scroll the tabs right",
        ["Posunúť záložky doľava"] = "Scroll the tabs left",
        ["Poznámka k titulu – uloží sa, keď pole opustíte. Vložená webová adresa sa zmení na slovo-odkaz vedľa poznámky."] = "Note on the title – saved when you leave the field. A pasted web address turns into a link word next to the note.",
        ["Poznámka s textom, štítkami, farbou a hlasom"] = "A note with text, tags, color and voice",
        ["Počas spracovania sa nič nemaže; po dokončení pošle originály do Koša tlačidlo Zmazať originály"] = "Nothing is deleted during processing; when it is done, the Delete the originals button sends the originals to the Recycle Bin",
        ["Pravidlá titulky.com dovoľujú len prehliadač: stiahnite titulky, UNIVERSUM ich sám vezme zo Stiahnutých súborov"] = "The titulky.com rules allow only a browser: download the subtitles, UNIVERSUM takes them from Downloads by itself",
        ["Pre vybranú skupinu naraz: druh, názov seriálu alebo filmu, čísla epizód aj jazyky stôp podľa návrhov (nie otázky Season 00 / bežná sezóna a návrhy s upozornením)"] = "For the selected group at once: kind, series or film title, episode numbers and track languages from the suggestions (not the Season 00 / regular season questions and suggestions with a warning)",
        ["Premiéry a epizódy len titulov zaškrtnutých vo Vybrané"] = "Premieres and episodes only of titles ticked in Selected",
        ["Presne podľa TMDB: číslo filmu (napr. 12345) alebo adresa z themoviedb.org; minisériál vložte ako adresu …/tv/…. Použije sa, keď pole opustíte."] = "Exactly by TMDB: film number (e.g. 12345) or address from themoviedb.org; paste a miniseries as a …/tv/… address. It is used when you leave the field.",
        ["Prečíta oba zvuky celé a porovná ich v mnohých častiach filmu: posun aj zmena FPS (25 ↔ 23,976); istý výsledok sa nastaví sám"] = "Reads both audio tracks in full and compares them in many parts of the film: shift and FPS change (25 ↔ 23.976); a certain result is set by itself",
        ["Pridajú sa ku kapitolám zo zdrojov, pri ktorých sú zaškrtnuté"] = "Added to the chapters from the sources where they are ticked",
        ["Pridaný externý súbor sa nepridá"] = "The added external file will not be added",
        ["Pridaný zvuk sa nepridá"] = "The added audio will not be added",
        ["Pridá súbor do fronty úloh namiesto okamžitého spracovania"] = "Adds the file to the job queue instead of processing it right away",
        ["Pridá vybranú dávku do Fronty úloh a spustí ju"] = "Adds the selected batch to the Job queue and starts it",
        ["Pridá zmenu do fronty úloh namiesto okamžitého uloženia"] = "Adds the change to the job queue instead of saving it right away",
        ["Pripojí súbory na koniec vybraného súboru – pokračujú jeho stopami (napr. 2. časť filmu)"] = "Appends files to the end of the selected file – they continue its tracks (e.g. part 2 of a film)",
        ["Pripravené súbory uloží do dávky MEGA spracovania – zapíšu sa neskôr (keď dávku spustíte, po predchádzajúcej dávke alebo v nastavenom čase)"] = "Saves the prepared files to a MEGA processing batch – they are written later (when you start the batch, after the previous batch or at the set time)",
        ["Prázdne = podľa súboru; pre staré české a slovenské titulky zvyčajne cp1250"] = "Empty = from the file; for old Czech and Slovak subtitles usually cp1250",
        ["Rozhodnutie platí pre všetky súbory skupiny"] = "The decision applies to all files of the group",
        ["Rýchla poznámka – prvá veta je názov, #slová sú štítky; Enter ju pridá"] = "Quick note – the first sentence is the title, #words are tags; Enter adds it",
        ["Single spracovanie originály vždy zachová – mazanie originálov je len v Hromadnom spracovaní."] = "Single processing always keeps the originals – deleting originals is only in Batch processing.",
        ["Slová, ktorými si čítanie nebolo isté, opraví podľa slovníka z vašich titulkov a slov, ktoré vo filme prečítalo isto; každú opravu môžete vrátiť"] = "Corrects the words the reading was not sure of, using the lexicon from your subtitles and the words it read with certainty in the film; you can revert each correction",
        ["Spresní navrhnuté názvy filmov podľa TMDB a overí ich v katalógu HISTRA; bez kľúča TMDB hľadá v HISTRA (len presná zhoda názvu a roku)"] = "Refines the suggested film titles by TMDB and verifies them in the HISTRA catalog; without a TMDB key it searches HISTRA (exact title and year match only)",
        ["Spustí spracovanie ako úlohu vo Fronte úloh (priebeh aj výstup každého súboru uvidíte aj tam)"] = "Starts processing as a job in the Job queue (you also see the progress and output of each file there)",
        ["Späť na predvolený výstup: vedľa prvého zdroja, s názvom podľa pravidiel, ak je zadaný titul"] = "Back to the default output: next to the first source, named by the rules if a title is entered",
        ["Synchronizácia podľa dvoch titulkov: najbližší titulok patrí sem (na začiatku filmu)"] = "Sync by two subtitles: the nearest subtitle belongs here (at the start of the film)",
        ["Súbor sa nemení; v Hromadnom spracovaní sa znova ukáže ako voľný"] = "The file does not change; it shows up as free in Batch processing again",
        ["Súbor sa so všetkými rozhodnutiami zapíše neskôr v MEGA spracovaní (keď dávku spustíte alebo v nastavenom čase); originál ostane"] = "The file is written with all decisions later in MEGA processing (when you start the batch or at the set time); the original stays",
        ["Súbory dokončenej dávky, ktoré sa preskočili, nepodarili alebo zrušili, sa znova skontrolujú a zapíšu"] = "Files of the finished batch that were skipped, failed or canceled are checked and written again",
        ["Súbory sa nemenia; nezapísané sa v Hromadnom spracovaní znova ukážu ako voľné"] = "The files do not change; those not written show up as free in Batch processing again",
        ["Súbory sa prečítajú ako jeden s vybraným súborom (napr. VTS_01_1.VOB, VTS_01_2.VOB)"] = "The files are read as one with the selected file (e.g. VTS_01_1.VOB, VTS_01_2.VOB)",
        ["Súbory titulkov (SRT, ASS/SSA, WebVTT, TTML, SAMI, SubViewer, MicroDVD, MPL2, TMPlayer) – uložia sa ako nové SRT"] = "Subtitle files (SRT, ASS/SSA, WebVTT, TTML, SAMI, SubViewer, MicroDVD, MPL2, TMPlayer) – saved as new SRT",
        ["Súbory titulkov, ktoré patria k videu – pridajú sa ako nové stopy (textové ako SRT v UTF-8)"] = "Subtitle files that belong to the video – added as new tracks (text ones as SRT in UTF-8)",
        ["Tento návrh sa už neukáže"] = "This suggestion will not show again",
        ["Tlač s náhľadom, PDF, HTML, Markdown, CSV"] = "Print with preview, PDF, HTML, Markdown, CSV",
        ["Tlač s náhľadom, PDF, HTML, iCalendar (.ics), CSV a záloha"] = "Print with preview, PDF, HTML, iCalendar (.ics), CSV and backup",
        ["Tlač s náhľadom, PDF, HTML, iCalendar, CSV, Markdown"] = "Print with preview, PDF, HTML, iCalendar, CSV, Markdown",
        ["Tvar je napísaný text (Enter); UNIVERSUM si ho zapamätá"] = "The shape is the typed text (Enter); UNIVERSUM remembers it",
        ["Urobí z návrhu úlohu"] = "Turns the suggestion into a task",
        ["V poradí, v akom budú vo výstupnom súbore; nezaškrtnuté stopy sa nevezmú"] = "In the order they will have in the output file; unticked tracks are left out",
        ["V prehrávači UNIVERSUM so zvukmi a titulkami výsledku"] = "In the UNIVERSUM player with the result's audio and subtitles",
        ["V texte bude „�“ – opravíte ho v Časoch titulkov"] = "The text will contain “�” – correct it in Subtitle times",
        ["Vráti úpravu hlavičky, ktorú urobila táto úloha"] = "Reverts the header edit made by this job",
        ["Vyberte priečinok s vašimi textovými titulkami (SRT, ASS, VTT, SUB), napr. knižnicu – UNIVERSUM si z nich zapamätá slová každého jazyka (len v tomto počítači, každý súbor raz)"] = "Choose the folder with your text subtitles (SRT, ASS, VTT, SUB), e.g. the library – UNIVERSUM remembers the words of each language from them (only on this computer, each file once)",
        ["Vyberte v zozname stopu s obrázkovými titulkami (PGS) – stopu videa alebo súbor .sup"] = "Choose a track with picture subtitles (PGS) in the list – a track of the video or a .sup file",
        ["Vybrané titulky preloží AI cez váš účet svsub.net (token v Nastaveniach); posielajú sa len titulky pod neutrálnym názvom"] = "AI translates the selected subtitles via your svsub.net account (token in Settings); only the subtitles are sent, under a neutral name",
        ["Vybrať priečinok a meno výstupného súboru"] = "Choose the folder and name of the output file",
        ["Vymaže náhľady Zlučovania v tomto priečinku (len súbory „… – náhľad …“, ktoré vytvoril UNIVERSUM)"] = "Deletes the Multiplexing previews in this folder (only the “… – náhľad …” files created by UNIVERSUM)",
        ["Vyplní názvy, jazyky, príznaky a poradie podľa pravidiel UNIVERSUM – potom sa dá ďalej upraviť"] = "Fills in the names, languages, flags and order by the UNIVERSUM rules – you can then edit further",
        ["Vyplní názvy, jazyky, príznaky a poradie vybraných stôp podľa pravidiel UNIVERSUM"] = "Fills in the names, languages, flags and order of the selected tracks by the UNIVERSUM rules",
        ["Vypnutím sa na HISTRA nič neposiela; uložený token ostáva."] = "When turned off, nothing is sent to HISTRA; the saved token stays.",
        ["Vypnutím sa na TMDB nič neposiela; uložený kľúč ostáva."] = "When turned off, nothing is sent to TMDB; the saved key stays.",
        ["Vypočuje si niekoľko úsekov z rôznych miest filmu a navrhne jazyk reči (whisper.cpp, všetko len v počítači; pár sekúnd na stopu). Vyberte, ktoré súbory."] = "Listens to several sections from different places in the film and suggests the spoken language (whisper.cpp, all on this computer only; a few seconds per track). Choose which files.",
        ["Výsledok (celý, nie náhľad) sa zapíše neskôr v MEGA spracovaní – keď dávku spustíte alebo v nastavenom čase. Zdrojové súbory ostanú."] = "The result (full, not a preview) is written later in MEGA processing – when you start the batch or at the set time. The source files stay.",
        ["Výsledok pôjde do knižnice (MOVIES / TVSHOWS) s názvom podľa pravidiel; cesta sa potom nedá upravovať."] = "The result goes to the library (MOVIES / TVSHOWS), named by the rules; the path then cannot be edited.",
        ["Zabudne analyzované, ešte nespracované súbory – aj poslané z Noviniek (na disku sa nič nezmení)"] = "Forgets the analyzed, not yet processed files – also those sent from News (nothing changes on the disk)",
        ["Zabudne otvorené video a titulky – na disku sa nič nezmení"] = "Forgets the open video and subtitles – nothing changes on the disk",
        ["Zabudne otvorené video a zvuky – na disku sa nič nezmení"] = "Forgets the open video and audio – nothing changes on the disk",
        ["Zabudne otvorené video – na disku sa nič nezmení"] = "Forgets the open video – nothing changes on the disk",
        ["Zabudne otvorený, ešte nespracovaný súbor (na disku sa nič nezmení)"] = "Forgets the open, not yet processed file (nothing changes on the disk)",
        ["Zapnuté: hlasy znejú rovnako, len pomalšie/rýchlejšie. Vypnuté: výška tónu sa zmení s rýchlosťou (vráti pôvodnú výšku zvuku zrýchleného pre PAL bez korekcie)"] = "On: voices sound the same, only slower/faster. Off: the pitch changes with the speed (restores the original pitch of audio sped up for PAL without correction)",
        ["Zapíše výsledok do priečinka náhľadov UNIVERSUM (nie do výstupného priečinka) – úseky sú hotové za chvíľu, celý film trvá ako zlučovanie"] = "Writes the result to the UNIVERSUM previews folder (not to the output folder) – sections are done in a moment, a whole film takes as long as multiplexing",
        ["Zastaví čítanie zvuku filmu"] = "Stops reading the film's audio",
