        ["Znova prečíta premiéry a epizódy, ktoré uchovávajú Premiéry a Novinky (zo zdrojov ich obnovíte tam)"] = "Rereads the premieres and episodes kept by Premieres and News (refresh them from the sources there)",
        ["Zobrazí vybraný súbor na stránke Informácie"] = "Shows the selected file on the Information page",
        ["Zobrazí vybraný zdrojový súbor (alebo súbor vybranej stopy) na stránke Informácie"] = "Shows the selected source file (or the file of the selected track) on the Information page",
