        ["Zvuk Windows: Hviezdička, keď je všetko hotové; Výkričník, keď niečo zlyhalo (aj Hromadné spracovanie)"] = "Windows sound: Asterisk when everything is done; Exclamation when something failed (Batch processing too)",
        ["Zvuk sa najprv celý zmeria, potom sa zapíše s rovnakou hlasitosťou ako ostatné filmy"] = "The audio is first measured in full, then written at the same volume as the other films",
