        ["Úprava titulkostopy: film s titulkami, časy, porovnanie – zmeny sa uložia do úlohy (Hromadné aj MEGA)"] = "Subtitle track editing: film with subtitles, times, comparison – the changes are saved to the job (Batch and MEGA)",
        ["Úsek, ktorý ostane, začína v čase prehrávača"] = "The section that remains starts at the player's time",
        ["Čakajúcu úlohu neskôr"] = "Move the waiting job later",
        ["Čakajúcu úlohu skôr"] = "Move the waiting job earlier",
        ["Čas spustenia, napr. 2:00"] = "Start time, e.g. 2:00",
        ["Číslo filmu na TMDB (napr. 1629051) alebo adresa themoviedb.org/movie/… – názov sa načíta presne podľa neho, aj pri filme v inom písme"] = "Film number on TMDB (e.g. 1629051) or a themoviedb.org/movie/… address – the title is loaded exactly by it, even for a film in another script",
        ["Číslo seriálu na TMDB (napr. 227191) alebo adresa themoviedb.org/tv/… – názov sa načíta presne podľa neho"] = "Series number on TMDB (e.g. 227191) or a themoviedb.org/tv/… address – the title is loaded exactly by it",
